mapper.select:
SELECT Q.*, QA.* FROM (
SELECT Q.*,
CASE WHEN SU.LOGIN_ID IS NOT NULL THEN SU.LOGIN_ID ELSE M.LOGIN_ID END AS LOGIN_ID, ( SELECT CASE WHEN LOCGOV.LOCGOV_CODE = LOCGOV.UPPER_LOCGOV_CODE THEN LOCGOV.UPPER_LOCGOV_NM ELSE CONCAT(LOCGOV.UPPER_LOCGOV_NM, ' ', LOCGOV.LOCGOV_NM) END FROM G_LOCGOV LOCGOV WHERE LOCGOV.LOCGOV_CODE = SU.LOCGOV_CODE ) AS LOCGOV_NAME FROM G_QNA_ADMIN Q
LEFT JOIN OP_SELLER_USER SU ON Q.USER_ID = SU.USER_ID LEFT JOIN OP_MANAGER M ON Q.USER_ID = M.USER_ID
AND Q.DATA_STATUS_CODE = '0' AND Q.DISPLAY_FLAG = 'Y'
AND Q.QNA_GROUP = #{qnaGroup}
AND Q.QNA_TYPE = #{qnaType}
AND Q.ITEM_ID = #{itemId}
AND Q.USER_ID = #{userId}
AND Q.CREATED_DATE >= TIMESTAMP(CONCAT(#{searchStartDate}, '000000'), 'yyyyMMddHHmmss')
AND Q.CREATED_DATE <= TIMESTAMP(CONCAT(#{searchEndDate}, '235959'), 'yyyyMMddHHmmss')
AND Q.ANSWER_COUNT > 0
AND Q.ANSWER_COUNT = 0
AND Q.USER_NAME LIKE CONCAT('%', #{query} , '%')
AND LOGIN_ID LIKE CONCAT('%', #{query} , '%')
AND Q.EMAIL LIKE CONCAT('%', #{query} , '%')
AND Q.SUBJECT LIKE CONCAT('%', #{query} , '%')
AND Q.QUESTION LIKE CONCAT('%', #{query} , '%')
AND Q.QNA_GROUP = #{query}
AND Q.DISPLAY_FLAG = #{displayFlag}
AND Q.LOCGOV_CODE = #{locgovCode}
AND Q.LOCGOV_CODE IN ( SELECT LOCGOV.LOCGOV_CODE FROM G_LOCGOV LOCGOV WHERE LOCGOV.UPPER_LOCGOV_CODE = #{upperLocgovCode} )
ORDER BY Q.CREATED_DATE DESC
) Q LEFT JOIN G_QNA_ADMIN_ANSWER QA ON Q.QNA_ADMIN_ID = QA.QNA_ADMIN_ID AND QA.DATA_STATUS_CODE = '0'


SELECT
	COUNT(1) AS CNT
FROM G_QNA_ADMIN Q



